<?php
require __DIR__.'/workflow_checks.php';
use Illuminate\Support\Facades\DB;
use App\Services\{ReturnRouting,Workflow,PickupRequests,Dispatch,AreaRouting};
use Illuminate\Http\UploadedFile;
$before=$n;
// Restore the delivered fixture for a return; all data is disposable SQLite.
DB::table('orders')->where('id',$oid)->update(['status'=>'DELIVERED','delivered_at'=>now(),'refunded_at'=>null]);
DB::table('parcels')->where('id',$pid)->update(['status'=>'DELIVERED']);
DB::table('return_requests')->where('order_id',$oid)->delete();
$id=DB::table('return_requests')->insertGetId(['order_id'=>$oid,'buyer_id'=>$buyer,'seller_id'=>$seller,'reason'=>'Damaged','description'=>'Damaged test product','photos'=>'[]','video_path'=>'return-videos/example.mp4','created_at'=>now(),'updated_at'=>now()]);
loginAs($seller);DB::transaction(fn()=>ReturnRouting::start(DB::table('return_requests')->find($id)));DB::table('return_requests')->where('id',$id)->update(['status'=>'approved']);
$rp=DB::table('parcels')->find($pid);ok($rp->return_request_id==$id&&$rp->status==='PREPARING','Approved return starts reverse pickup');
ok(ReturnRouting::pickup($rp)->recipient===json_decode(DB::table('orders')->find($oid)->address_snapshot)->recipient,'Return pickup uses buyer snapshot');
ok(ReturnRouting::destination($rp)->user_id==$seller,'Return destination uses seller snapshot');
$a=DB::table('assignments')->where('parcel_id',$pid)->where('kind','pickup')->orderByDesc('id')->first();ok($a->handling_center_id==$rp->center_id,'Return pickup visible to origin center');
loginAs($buyer);try{App\Services\Commerce::cancel($oid,'Cannot cancel reverse pickup',$buyer);throw new RuntimeException('Return cancelled as outbound order');}catch(Illuminate\Validation\ValidationException $e){ok(isset($e->errors()['order']),'Approved return cannot be cancelled as an outbound order');}
$c=DB::table('sorting_centers')->find($rp->center_id);$localRider=$rider;DB::table('users')->where('id',$localRider)->update(['online'=>1,'last_seen_at'=>now(),'company_id'=>$c->user_id]);
loginAs($c->user_id);PickupRequests::offer($a->id,$c->user_id,$localRider);loginAs($localRider);Dispatch::accept($a->id,$localRider);requestFor();Workflow::move($pid,'PICKED_UP',$localRider);Workflow::move($pid,'AT_SORTING_CENTER',$localRider);
ok(DB::table('parcels')->find($pid)->status==='AT_SORTING_CENTER','Return rider completes pickup at center');
loginAs($c->user_id);AreaRouting::sort($pid,$c->user_id);Dispatch::offer($pid,$c->user_id,$localRider);$delivery=DB::table('assignments')->where('parcel_id',$pid)->where('kind','delivery')->orderByDesc('id')->first();loginAs($localRider);Dispatch::accept($delivery->id,$localRider);requestFor();Workflow::move($pid,'OUT_FOR_DELIVERY',$localRider);
$collections=DB::table('cod_collections')->count();$entries=DB::table('wallet_entries')->count();$originalProof=DB::table('parcels')->find($pid)->proof_path;
$tmp=tempnam(sys_get_temp_dir(),'return-proof');file_put_contents($tmp,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jD9sAAAAASUVORK5CYII='));
requestFor(['scanned_code'=>DB::table('parcels')->find($pid)->tracking_code],['proof'=>new UploadedFile($tmp,'return.png','image/png',null,true)]);Workflow::move($pid,'DELIVERED',$localRider);
ok(DB::table('parcels')->find($pid)->status==='RETURNED','Return delivery waits for seller confirmation');ok(DB::table('cod_collections')->count()===$collections,'Return never collects COD twice');ok(DB::table('wallet_entries')->count()===$entries,'Return never repeats shipping earnings');ok(DB::table('parcels')->find($pid)->proof_path===$originalProof&&DB::table('parcels')->find($pid)->return_proof_path,'Return proof preserves outbound proof');
loginAs($seller);Workflow::move($pid,'RETURN_RECEIVED',$seller);ok(DB::table('return_requests')->find($id)->status==='received','Seller receipt closes return');
@unlink($tmp);echo 'PASS: '.($n-$before)." reverse-return checks.\n";
// A reverse parcel crosses centers using the existing bulk transfer workflow.
$beforeTransfer=$n;$owner=user('sorting_center','return_destination');$dest=DB::table('sorting_centers')->insertGetId(['user_id'=>$owner,'name'=>'Seller return center','city'=>'Bay','province'=>'Laguna','municipality_key'=>App\Services\Municipalities::key('Laguna','Bay')]);$sellerAddress=['recipient'=>'Return seller','phone'=>'09170000000','street'=>'Seller street','barangay'=>'Poblacion','city'=>'Bay','province'=>'Laguna'];DB::table('addresses')->insert($sellerAddress+['user_id'=>$owner,'is_default'=>1]);
$reverseOrder=DB::table('orders')->insertGetId(['buyer_id'=>$buyer,'seller_id'=>$seller,'address_id'=>$address,'address_snapshot'=>json_encode(ReturnRouting::buyer(DB::table('orders')->find($oid))),'status'=>'AT_SORTING_CENTER','total'=>150,'shipping_fee'=>50,'merchandise_total'=>100,'created_at'=>now(),'updated_at'=>now()]);$returnId=DB::table('return_requests')->insertGetId(['order_id'=>$reverseOrder,'buyer_id'=>$buyer,'seller_id'=>$seller,'status'=>'approved','reason'=>'Damaged','description'=>'Reverse transfer test','photos'=>'[]','pickup_snapshot'=>json_encode(ReturnRouting::buyer(DB::table('orders')->find($oid))),'destination_snapshot'=>json_encode($sellerAddress),'created_at'=>now(),'updated_at'=>now()]);$reverseParcel=DB::table('parcels')->insertGetId(['order_id'=>$reverseOrder,'return_request_id'=>$returnId,'tracking_code'=>'RETURN-XFER-TEST','status'=>'AT_SORTING_CENTER','center_id'=>$c->id,'created_at'=>now(),'updated_at'=>now()]);
$driver=user('rider','return_driver');DB::table('users')->where('id',$driver)->update(['company_id'=>$c->user_id,'courier_type'=>'driver','online'=>1,'last_seen_at'=>now()]);loginAs($c->user_id);$trip=App\Services\BulkTrips::create($c->user_id,$driver,[$reverseParcel]);ok(DB::table('parcels')->find($reverseParcel)->destination_center_id==$dest,'Reverse transfer chooses seller center rather than buyer center');loginAs($driver);App\Services\BulkTrips::accept($trip,$driver);App\Services\BulkTrips::depart($trip,$driver);$stop=DB::table('driver_trip_stops')->where('trip_id',$trip)->first();App\Services\BulkTrips::handover($stop->id,$driver);loginAs($owner);App\Services\BulkTrips::receive($stop->id,$owner,[$reverseParcel]);ok(DB::table('parcels')->find($reverseParcel)->center_id==$dest&&DB::table('parcels')->find($reverseParcel)->status==='AT_SORTING_CENTER','Seller center receives return through existing driver handover');echo 'PASS: '.($n-$beforeTransfer)." reverse inter-center transfer checks.\n";
